class BoundedQueue:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.queue = deque()
        self.cv = threading.Condition()

    def push(self, val) -> None:
        with self.cv:
            while len(self.queue) == self.capacity:
                self.cv.wait()
            self.queue.append(val)
            self.cv.notify_all()

    def pop(self):
        with self.cv:
            while not self.queue:
                self.cv.wait()
            val = self.queue.popleft()
            self.cv.notify_all()
            return val

